/*
 * Preconceived notions: for each narrative that states one, what people
 * expected at the time and what actually happened, in a sentence each.
 *
 * gam (2026-11-26) asked for "areas of preconceived notions" and a more
 * concise story year over year. These lines are the short version of the
 * narrative they belong to: each is paraphrased only from that narrative's
 * summary (and so from its sources), never from hindsight or memory, and the
 * narrative itself is unchanged. A few outcomes for the season just finished
 * come from the Basketball Reference snapshot and say so.
 *
 * Verdict: did the consensus (or the on-paper expectation) hold?
 *   held    the favorite or the expectation came through
 *   busted  it went the other way
 *   mixed   part of it came true
 *   open    the season is still being played
 */

export type NotionVerdict = 'held' | 'busted' | 'mixed' | 'open';
/** Expected at the time, what happened, verdict. Keyed by story id. */
export type Notion = [expected: string, happened: string, verdict: NotionVerdict];

export const NOTION_VERDICTS: Record<NotionVerdict, string> = {
  held: 'Consensus held',
  busted: 'Consensus busted',
  mixed: 'Partly right',
  open: 'Still playing out',
};

